-- ==========================================
-- SEED: Cities
-- ==========================================
-- Populated from src/backend_lib/shared/data/cities.json (keys = ISO 3166-1 alpha-2).
-- country_id is NOT hardcoded: each row joins public.countries on iso_code so FKs stay
-- correct no matter which UUIDs were assigned when countries were seeded (003_countries.sql).
--
-- Re-run safe: ON CONFLICT (country_id, name) DO NOTHING (matches uq_cities_country_name).
-- created_at / updated_at: one minute apart per row (same idea as 003_countries.sql), using
-- ROW_NUMBER() * INTERVAL '1 minute' so every city has a distinct timestamp for cursor pagination
-- without embedding ~150k literal INTERVAL lines.
-- Regenerate this file after changing cities.json: pnpm run seed:build-cities

INSERT INTO cities (country_id, name, created_at, updated_at)
SELECT country_id,
       city_name,
       NOW() - ((rn - 1) * INTERVAL '1 minute'),
       NOW() - ((rn - 1) * INTERVAL '1 minute')
FROM (
    SELECT co.id AS country_id,
           t.city_name,
           ROW_NUMBER() OVER (ORDER BY e.iso_code, t.city_name) AS rn
    FROM (
        SELECT convert_from(decode('', 'base64'), 'UTF8')::jsonb AS doc
    ) raw
    CROSS JOIN LATERAL jsonb_each(raw.doc) AS e(iso_code, city_array)
    JOIN countries co ON co.iso_code::text = e.iso_code
    CROSS JOIN LATERAL jsonb_array_elements_text(e.city_array) AS t(city_name)
    WHERE jsonb_typeof(e.city_array) = 'array'
      AND jsonb_array_length(e.city_array) > 0
) ranked
ON CONFLICT (country_id, name) DO NOTHING;
